      '<span class="rew">' + lv.moons + "🌙<small>+" + lv.xp + " XP</small></span>";
    if(open) b.onclick = () => { ResumeAudio(); startLevel(i); showScreen("game"); };
    ll.appendChild(b);
  });

  // unit upgrade cards
  const ul = document.getElementById("unitList"); ul.innerHTML = "";
  UNIT_IDS.forEach(id => {
