      '<span class="info"><b>' + u.name + ' <em style="color:#ffd700">Lv ' + lv + (lv >= 5 ? " MAX" : "/5") + "</em></b>" +
      "<span>" + u.desc + "</span>" +
      '<em>Biaya ' + u.cost + "★ · HP " + Math.round(u.hp * upgMult(id)) +
      (u.dmg ? " · DMG " + Math.round(u.dmg * upgMult(id)) : "") + "</em></span>";
    const btn = document.createElement("button");
