      (got ? a.desc : "?? " + a.desc) + "</span></span>" + '<span class="gem">💎' + a.gem + "</span>";
    al.appendChild(d);
  });

  // daily
  const today = new Date().toISOString().slice(0, 10);
  const bd = document.getElementById("btnDaily");
